#!/usr/bin/env python3
"""Ensure this project can only ship native Android and iOS builds."""
from pathlib import Path
import re
import sys

root = Path(__file__).resolve().parent.parent
issues = []

# These are generated by Godot's Web export and do not belong in this repo.
for asset in sorted(root.glob("index.*")):
    if asset.is_file():
        issues.append(f"Web export artifact: {asset.relative_to(root)}")

for path in (
    ".nojekyll", "404.html", "CNAME", "manifest.webmanifest",
    "service-worker.js", "web/index.html", "docs/index.html",
    "ci/finish_web.py", ".github/workflows/pages.yml",
    ".github/workflows/deploy-pages.yml",
    ".github/workflows/github-pages.yml",
):
    if (root / path).is_file():
        issues.append(f"Web publication file: {path}")

presets = root / "source/export_presets.cfg"
if presets.is_file() and re.search(
    r'^\s*platform\s*=\s*["\'](?:Web|HTML5)["\']',
    presets.read_text(encoding="utf-8"),
    flags=re.MULTILINE | re.IGNORECASE,
):
    issues.append("Godot Web export preset is not permitted")

workflows = root / ".github/workflows"
for path in sorted(workflows.glob("*")):
    if path.suffix.lower() not in (".yml", ".yaml"):
        continue
    contents = path.read_text(encoding="utf-8").lower()
    for forbidden in (
        "actions/deploy-pages", "actions/upload-pages-artifact",
        "actions/configure-pages", "peaceiris/actions-gh-pages",
        "pages-build-deployment", "--export-debug web",
        "--export-release web",
    ):
        if forbidden in contents:
            issues.append(f"{path.relative_to(root)} uses {forbidden}")

if issues:
    print("NATIVE_ONLY_CHECK_FAILED", file=sys.stderr)
    for issue in issues:
        print(" - " + issue, file=sys.stderr)
    sys.exit(1)

print("NATIVE_ONLY_CHECK_OK")
